#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
  int fd = open("my_file.txt", O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    perror("open failed");
    return 1;
  }
  const char *message = "Hello, system call!";
  ssize_t bytes_written = write(fd, message, sizeof(message) -1);
    if (bytes_written == -1) {
    perror("write failed");
    return 1;
  }
  close(fd);
  return 0;
}
